import { GetAllCategories } from "@/mixins/GetAllCategories";
export default {
  mixins: [GetAllCategories],
  components: {
    ScheduleGameDialog,
    ScheduledGames,
    SnackBar
  },
  data: () => ({
    search: "",
    windowHeight: 0,
    currentPage: 1,
    itemsPerPage: 15,
    DialogScheduleGame: false,
    loading: false,
    SnackBarComponent: {},
    ListAllCategories: [],
    TableHeaders: [{
      title: "Category Name",
      value: "splay_category_name",
      width: "45%"
    }, {
      title: "Questions",
      value: "question_count",
      width: "45%"
    }, {
      title: "Action",
      value: "action"
    }]
  }),
  computed: {
    totalItems() {
      return this.ListAllCategories.length;
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.ListAllCategories.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.ListAllCategories.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  async mounted() {
    this.windowHeight = window.innerHeight - 243;
    await this.GetAllCategoriesMethod();
  },
  methods: {
    OpenDialogScheduleGame(item) {
      this.StoreObj = item;
      this.DialogScheduleGame = true;
    },
    DialogScheduleGameEmit() {
      this.DialogScheduleGame = false;
    }
  }
};
